  CONSTRAINT `gateentries_ibfk_2` FOREIGN KEY (`studentId`) REFERENCES `Users` (`id`),
  CONSTRAINT `gateentries_ibfk_3` FOREIGN KEY (`securityPersonId`) REFERENCES `Users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
